#pragma once
class LocalMultiEdits {
public:
 static juce::File location(juce::File source){auto path=source.getFullPathName();return LibraryStore::root().getChildFile("multi-edits").getChildFile(juce::SHA256(path.toRawUTF8(),path.getNumBytesAsUTF8()).toHexString()+".xml");}
 static std::unique_ptr<juce::XmlElement> load(juce::File source){source=LibraryStore::resolveFile(source);auto x=juce::parseXML(location(source));if(!x)x=juce::parseXML(LibraryStore::read("multi-edits.json").getProperty(source.getFullPathName(),{}).toString());if(!x||LibraryStore::resolveFile(juce::File(x->getStringAttribute("localSource")))!=source||x->getStringAttribute("localStamp")!=juce::String(source.getLastModificationTime().toMilliseconds())||x->getStringAttribute("localSize")!=juce::String(source.getSize()))return {};return x;}
 static bool indexFolder517(juce::File folder){juce::Array<juce::File> files;if(folder.isDirectory())files=folder.findChildFiles(juce::File::findFiles,true,"*.sfz");else if(folder.hasFileExtension("sfz"))files.add(folder);juce::var indexed(new juce::DynamicObject());for(auto file:files)if(auto xml=load(file))indexed.getDynamicObject()->setProperty(file.getFullPathName(),xml->toString());if(indexed.getDynamicObject()->getProperties().size()==0)return true;return LibraryStore::update("multi-edits.json",[&](auto& o){for(auto& item:indexed.getDynamicObject()->getProperties())o.setProperty(item.name,item.value);});}

 static bool save(juce::File source,const juce::String& text){source=LibraryStore::resolveFile(source);auto x=juce::parseXML(text);if(!x)return false;x->setAttribute("localSource",source.getFullPathName());x->setAttribute("localStamp",juce::String(source.getLastModificationTime().toMilliseconds()));x->setAttribute("localSize",juce::String(source.getSize()));auto file=location(source);if(!file.getParentDirectory().createDirectory())return false;juce::TemporaryFile temp(file);return temp.getFile().replaceWithText(x->toString())&&temp.overwriteTargetFileWithTemporary();}
};
